#!/usr/bin/env bash
# Create-only fixed paired dual-car H8 subtree policy comparison.
# Does not edit the formal repo, old artifacts, datasets, or checkpoints.
if [ "$#" -ne 1 ] || [ "$1" != "--authorize-subtree-policy4-once" ]; then
  printf '%s\n' '用法：bash /root/autodl-tmp/run_dual_subtree_policy4.sh --authorize-subtree-policy4-once'
  exit 2
fi
printf '%s\n' '资源：HIGH-CPU，至少2有效CPU、2GiB可用内存与磁盘；单进程，不用GPU。固定4条策略续行，每条最多128步。512条教师数据不重采。'
DATA=/root/autodl-tmp
if [ ! -d "$DATA" ]; then printf '%s\n' 'HOLD：数据盘目录不存在，不创建替代目录。'; exit 2; fi
LOG=$(mktemp "$DATA/run_dual_subtree_policy4.XXXXXXXX.log") || exit 2
printf 'LAUNCHER_LOG=%s\n' "$LOG"
(
  set -e
  cd /root/MineSim-Dynamic
  source /root/miniconda3/etc/profile.d/conda.sh
  conda activate minesim
  export PYTHONPATH=/root/MineSim-Dynamic
  export PYTHONDONTWRITEBYTECODE=1
  export CUDA_VISIBLE_DEVICES=""
  export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
  python -B - <<'PY_RELEASE'
import base64,hashlib,io,json,os,zipfile
from pathlib import Path,PurePosixPath
raw=base64.b64decode('',validate=True)
expected='04393be789c50fea64e1cb78704f162eb1b6fdf7adae5a4cbe742345b11e120b'
if hashlib.sha256(raw).hexdigest()!=expected:raise RuntimeError('PAYLOAD_SHA')
root=Path('/root/autodl-tmp/minesim_dual_subtree_h8_policy4_v1_release')
for p in [root]+list(root.parents):
    if p.is_symlink():raise RuntimeError('RELEASE_SYMLINK:'+str(p))
root.mkdir(exist_ok=True)
with zipfile.ZipFile(io.BytesIO(raw)) as z:
    names=z.namelist()
    if len(set(names))!=len(names):raise RuntimeError('DUPLICATE_MEMBERS')
    manifest=json.loads(z.read('RELEASE_MANIFEST.json'))
    if set(names)!=set(manifest)|{'RELEASE_MANIFEST.json'}:raise RuntimeError('MEMBER_SET')
    for n in names:
        rel=PurePosixPath(n)
        if rel.is_absolute() or '..' in rel.parts or '\\' in n or str(rel)!=n:raise RuntimeError('UNSAFE_MEMBER')
        b=z.read(n)
        if n in manifest and manifest[n]!={'size':len(b),'sha256':hashlib.sha256(b).hexdigest()}:raise RuntimeError('MEMBER_SHA')
        dst=root/n
        for p in [dst]+list(dst.parents):
            if p.is_symlink():raise RuntimeError('MEMBER_SYMLINK')
        if os.path.lexists(dst):
            if not dst.is_file() or dst.read_bytes()!=b:raise RuntimeError('EXISTING_RELEASE_DIFFERS_NO_OVERWRITE:'+str(dst))
        else:
            dst.parent.mkdir(parents=True,exist_ok=True)
            with dst.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())
print('RELEASE_VERIFIED='+expected,flush=True)
PY_RELEASE
  python -B - <<'PY_RESOURCE'
import importlib.util
from pathlib import Path
p=Path('/root/autodl-tmp/minesim_dual_subtree_h8_policy4_v1_release/gate.py')
s=importlib.util.spec_from_file_location('resource_only',p);g=importlib.util.module_from_spec(s);s.loader.exec_module(g)
r=g.resources(Path('/root/autodl-tmp'))
print('RESOURCE_PREFLIGHT='+str(r),flush=True)
if not (r['effective_cpu']>=2 and r['memory_available_bytes']>=2*1024**3 and r['free_disk_bytes']>=2*1024**3):
    print('HOLD_RESOURCE_BEFORE_CLAIM：未创建实验lease/START，不做搜索。',flush=True)
    raise SystemExit(2)
PY_RESOURCE
  python -B -u /root/autodl-tmp/minesim_dual_subtree_h8_policy4_v1_release/gate.py --authorize-subtree-policy4-once
) >>"$LOG" 2>&1
RC=$?
tail -n 28 "$LOG"
printf 'LAUNCHER_RC=%s\nLAUNCHER_LOG=%s\n' "$RC" "$LOG"
if [ "$RC" -ne 0 ]; then
  printf '%s\n' 'HOLD：保留结果、lease、pending和日志，不删除、不重跑。有BUNDLE上传对应ZIP，否则上传LAUNCHER_LOG。'
fi
exit "$RC"
